//! Repository for TaxTransaction entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the e-Faktur engine's tax-transaction SQL (4-layer rule: services orchestrate,
//! repos hold SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<TaxTransaction, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use chrono::NaiveDate;
use rust_decimal::Decimal;
use sqlx::{PgConnection, PgPool, Row};
use uuid::Uuid;

use crate::domain::entity::TaxTransaction;

/// Table name for TaxTransaction entities
pub const TABLE_NAME: &str = "tax.tax_transactions";

/// Repository for TaxTransaction entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct TaxTransactionRepository(
    backbone_orm::GenericCrudRepository<TaxTransaction, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for TaxTransactionRepository {
    type Target = backbone_orm::GenericCrudRepository<TaxTransaction, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl TaxTransactionRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row an idempotent tax-transaction upsert writes.
pub struct NewTaxTransactionRow<'a> {
    pub id: Uuid,
    pub company_id: Uuid,
    pub invoice_ref: Uuid,
    pub invoice_kind: &'a str,
    pub posting_date: NaiveDate,
    pub taxable_base: Decimal,
    pub output_total: Decimal,
    pub input_total: Decimal,
    pub withholding_total: Decimal,
}

/// Tax-transaction SQL. Lives here (not in the service) per the module's 4-layer rule.
impl TaxTransactionRepository {
    /// Idempotent insert (unique `company + invoice_ref + invoice_kind` fence). On conflict, the
    /// `DO UPDATE SET status = tax.tax_transactions.status` is a no-op that lets `RETURNing id`
    /// surface the existing row's id — so a re-delivery of a posted billing event returns the
    /// original transaction id instead of erroring. The caller has already bound the company on
    /// `conn` via `bind_company_on`; the explicit `company_id` bind is defense-in-depth on top of
    /// the RLS fence. The `$4::invoice_kind` cast and `'recorded'::tax_transaction_status` literal
    /// are preserved verbatim from the hand-written original.
    pub async fn upsert_recorded(
        &self,
        conn: &mut PgConnection,
        r: &NewTaxTransactionRow<'_>,
    ) -> Result<Uuid, sqlx::Error> {
        let row = sqlx::query(
            r#"INSERT INTO tax.tax_transactions
                 (id, company_id, invoice_ref, invoice_kind, posting_date, taxable_base,
                  output_total, input_total, withholding_total, status)
               VALUES ($1, $2, $3, $4::invoice_kind, $5, $6, $7, $8, $9, 'recorded'::tax_transaction_status)
               ON CONFLICT (company_id, invoice_ref, invoice_kind) WHERE (metadata->>'deleted_at') IS NULL
               DO UPDATE SET status = tax.tax_transactions.status
               RETURNING id"#,
        )
        .bind(r.id).bind(r.company_id).bind(r.invoice_ref)
        .bind(r.invoice_kind).bind(r.posting_date).bind(r.taxable_base)
        .bind(r.output_total).bind(r.input_total).bind(r.withholding_total)
        .fetch_one(conn).await?;
        let id: Uuid = row.get("id");
        Ok(id)
    }

    /// Look up the e-Faktur document already attached to a transaction (if any). Used by the
    /// recording path to make sales e-Faktur assignment idempotent across re-deliveries. The
    /// `efaktur_document_id` column is nullable, so the scalar returns `Option<Uuid>`; a row is
    /// guaranteed to exist (the caller just upserted it), so `fetch_one` cannot miss here.
    pub async fn find_efaktur_id(
        &self,
        conn: &mut PgConnection,
        txn_id: Uuid,
    ) -> Result<Option<Uuid>, sqlx::Error> {
        let existing: Option<Uuid> = sqlx::query_scalar(
            "SELECT efaktur_document_id FROM tax.tax_transactions WHERE id = $1",
        )
        .bind(txn_id)
        .fetch_one(conn)
        .await?;
        Ok(existing)
    }

    /// Attach the freshly-assigned e-Faktur document id to a transaction. The caller has already
    /// bound the company on `conn`; the row is company-scoped via its `id` (which is globally
    /// unique), so no extra `company_id` filter is needed.
    pub async fn attach_efaktur(
        &self,
        conn: &mut PgConnection,
        txn_id: Uuid,
        efaktur_id: Uuid,
    ) -> Result<(), sqlx::Error> {
        sqlx::query("UPDATE tax.tax_transactions SET efaktur_document_id = $2 WHERE id = $1")
            .bind(txn_id)
            .bind(efaktur_id)
            .execute(conn)
            .await?;
        Ok(())
    }

    /// Find the e-Faktur document (if any) attached to the live tax transaction for a given invoice.
    /// Used by the cancellation/void path: given a billing `invoice_ref` (+ kind), resolve the
    /// e-Faktur to void. Returns `None` when there is no transaction or no e-Faktur attached (purchase
    /// invoices, or a sales invoice not yet numbered) — the caller treats that as a no-op.
    pub async fn find_efaktur_id_by_invoice(
        &self,
        conn: &mut PgConnection,
        company_id: Uuid,
        invoice_ref: Uuid,
        invoice_kind: &str,
    ) -> Result<Option<Uuid>, sqlx::Error> {
        let id: Option<Option<Uuid>> = sqlx::query_scalar(
            r#"SELECT efaktur_document_id FROM tax.tax_transactions
               WHERE company_id = $1 AND invoice_ref = $2 AND invoice_kind = $3::invoice_kind
                 AND (metadata->>'deleted_at') IS NULL"#,
        )
        .bind(company_id)
        .bind(invoice_ref)
        .bind(invoice_kind)
        .fetch_optional(conn)
        .await?;
        Ok(id.flatten())
    }

    /// Find the live tax transaction id for a given invoice, if one exists. The idempotency probe
    /// the recording path runs BEFORE the filing-period guard: a re-delivery of an event whose
    /// transaction landed before the period closed must stay a committed no-op, never a refusal.
    pub async fn find_id_by_invoice(
        &self,
        conn: &mut PgConnection,
        company_id: Uuid,
        invoice_ref: Uuid,
        invoice_kind: &str,
    ) -> Result<Option<Uuid>, sqlx::Error> {
        let id: Option<Uuid> = sqlx::query_scalar(
            r#"SELECT id FROM tax.tax_transactions
               WHERE company_id = $1 AND invoice_ref = $2 AND invoice_kind = $3::invoice_kind
                 AND (metadata->>'deleted_at') IS NULL"#,
        )
        .bind(company_id)
        .bind(invoice_ref)
        .bind(invoice_kind)
        .fetch_optional(conn)
        .await?;
        Ok(id)
    }
}

backbone_core::impl_crud_repository!(TaxTransactionRepository, TaxTransaction, soft_delete);
